import {header,icon,escape,section} from '../ui.js';
import {getWord} from '../content.js';
export function render(state) {
 const pending=state.reviews.filter(r=>r.status==='pending'&&!r.paused); const scheduled=state.reviews.filter(r=>r.status==='planned'&&!r.paused);
 return `${header('按照你的节奏','学习计划 · 日常英语 A2 → B1')}<section class="goal-banner"><p class="eyebrow">YOUR NORTH STAR</p><h2>在日常场景里，<br>自信地说出来。</h2><p>阶段目标 · 旅行与生活表达</p></section>${section('每天留一点时间')}<form id="plan-form"><fieldset><legend>每天可用时间</legend><div class="budget-options">${[10,20,30,45].map(n=>`<label><input type="radio" name="budget" value="${n}" ${state.budget===n?'checked':''}><span>${n}<small>分钟</small></span></label>`).join('')}</div></fieldset><label class="field-label" for="plan-mode">计划方式</label><select id="plan-mode" name="mode"><option value="manual" ${state.mode==='manual'?'selected':''}>手动计划 · 我来决定</option><option value="assisted" ${state.mode==='assisted'?'selected':''}>教练辅助 · 建议后由我确认</option><option value="managed" ${state.mode==='managed'?'selected':''}>教练托管 · 在每日预算内调整</option></select><p class="small-note left">托管仅演示预算内安排；修改目标仍由你决定。</p><button class="secondary full">保存演示计划</button></form>
 ${pending.length?`${section('等待安排',`<span class="counter">${pending.length}</span>`)}${pending.map(r=>`<article class="pending-row"><div><strong>${getWord(r.wordId).word} · ${escape(r.skill)}</strong><p>你希望明天练 · 建议 19:30，3 分钟</p></div><button class="primary compact" data-action="schedule" data-id="${escape(r.id)}">确认安排</button></article>`).join('')}`:''}
 ${section('接下来的学习')}<div class="timeline"><div class="timeline-step"><span class="timeline-dot"></span><div><small>今天 · ${state.budget} 分钟预算</small><h3>回忆 → 新词 → 听辨</h3><p>${state.quiet?'静音学习已开启，口语练习保留待练。':'优先完成已有复习，再学三个新词。'}</p></div></div>${scheduled.map(r=>`<div class="timeline-step"><span class="timeline-dot pale"></span><div><small>${escape(r.when)}</small><h3>${getWord(r.wordId).word} · ${escape(r.skill)}练习</h3><p>${r.skill==='发音'?'示范、跟读、自听 · 未自动评测':'独立回忆，再对照答案'}</p></div></div>`).join('')}</div><div class="plan-explanation">${icon('bolt',18)}<p>为什么先复习？<br><span>先巩固已有内容，再用剩余时间学习新词。这里展示的是样例安排。</span></p></div>`;
}
